import React from "react";

export function moneyLabel(sum: number, code: string): string {
  const below = sum < 0;
  const magnitude = Math.abs(sum);
  const units = Math.floor(magnitude);
  const hundredths = Math.round((magnitude - units) * 100);
  const chars = String(units);
  let out = "";
  for (let n = 0; n < chars.length; n++) {
    const remaining = chars.length - n;
    out += chars[n];
    if (remaining > 1 && remaining % 3 === 1) {
      out += ",";
    }
  }
  const decimals = hundredths < 10 ? "0" + hundredths : String(hundredths);
  const minus = below ? "-" : "";
  return minus + out + "." + decimals + " " + code;
}

export const MoneyLabel = ({ sum, code }: { sum: number; code: string }) => (
  <span className="money">{moneyLabel(sum, code)}</span>
);

