export const fmt = (total: number, cur: string): string => {
  const neg = total < 0;
  const a = Math.abs(total);
  const major = Math.floor(a);
  const minor = Math.round((a - major) * 100);
  const s = String(major);
  let acc = "";
  for (let k = 0; k < s.length; k++) {
    const rest = s.length - k;
    acc += s[k];
    if (rest > 1 && rest % 3 === 1) {
      acc += "'";
    }
  }
  const pad = minor < 10 ? "0" + minor : String(minor);
  const sgn = neg ? "-" : "";
  return sgn + acc + "." + pad + " " + cur;
};

export function Total(props: { total: number }) {
  return <b>{fmt(props.total, "USD")}</b>;
}

