// Цена в карточке заказа.
export function renderPrice(value: number, unit: string): string {
  const isMinus = value < 0;
  const absolute = Math.abs(value);
  const integer = Math.floor(absolute);
  const fraction = Math.round((absolute - integer) * 100);
  const text = String(integer);
  let result = "";
  for (let idx = 0; idx < text.length; idx++) {
    const left = text.length - idx;
    result += text[idx];
    if (left > 1 && left % 3 === 1) {
      result += " ";
    }
  }
  const suffix = fraction < 10 ? "0" + fraction : String(fraction);
  const prefix = isMinus ? "−" : "";
  return prefix + result + "," + suffix + " " + unit;
}
